<script lang="ts">
 import {Search,X} from '@lucide/svelte';import {openReportLookup} from './report-settings';import {uid,type Project} from './model';import type {ReferenceKind} from './catalog-definitions';
 export let project:Project;export let kind:ReferenceKind|'accounts'|'services';export let value='';export let text='';export let parentId='';export let disabled=false;export let clearable=true;export let onselect:(id:string)=>void;export let oninspect:((id:string)=>void)|undefined=undefined;
 const fieldId=uid();$:label=kind==='accounts'?(project.accounts.find(a=>a.id===value)?.number||'')+' '+(project.accounts.find(a=>a.id===value)?.payer_name||''):kind==='services'?project.services.find(s=>s.id===value)?.name[project.settings.language]:project.reference_catalogs[kind]?.find(r=>r.id===value)?.name;
 function choose(){openReportLookup({id:fieldId,parentId,label:project.settings.language==='ru'?'Выбор элемента':'Selectare element',kind,items:[],selected:value?[value]:[],multiple:false,onchoose:ids=>onselect(ids[0]||'')});}
</script>
<div class="lookup-field"><input readonly value={text||label||''} aria-label={text||label||kind}/><button type="button" {disabled} title={project.settings.language==='ru'?'Выбрать':'Selectează'} onclick={choose}>…</button>{#if clearable}<button type="button" {disabled} title={project.settings.language==='ru'?'Очистить':'Golește'} onclick={()=>onselect('')}><X size={14}/></button>{/if}{#if oninspect}<button type="button" disabled={disabled||!value} title={project.settings.language==='ru'?'Открыть':'Deschide'} onclick={()=>oninspect?.(value)}><Search size={15}/></button>{/if}</div>
